import{_ as a,o as t,c as r,ak as o}from"./chunks/framework.C2AAou88.js";const p=JSON.parse('{"title":"About","description":"","frontmatter":{"sidebar":false,"aside":false,"prev":false,"next":false},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),i={name:"about.md"};function n(l,e,s,h,u,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h1><p>Latcher is built by <a href="https://github.com/pyepye" target="_blank" rel="noreferrer">Matt Pye</a>.</p><h2 id="why-i-built-it" tabindex="-1">Why I built it <a class="header-anchor" href="#why-i-built-it" aria-label="Permalink to &quot;Why I built it&quot;">​</a></h2><p>I have been building large scale Node applications on AWS Lambda for years.</p><p>One function per lambda never held up at any real scale. Once you have hundreds of them the deployment sprawls and nobody can say what handles what.</p><p>Grouping code by business logic instead of by AWS service worked much better. An entity lives in one place, whether it arrives over HTTP or off a queue.</p><p>I could never find a framework that was comfortable with all of this. The ones I tried handled API Gateway well and left every other event source to me. So I built this one.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>The source lives on GitHub at <a href="https://github.com/pyepye/latcher" target="_blank" rel="noreferrer">pyepye/latcher</a>.</p>',9)])])}const b=a(i,[["render",n]]);export{p as __pageData,b as default};
